  /// Количество клубов с найденной эмблемой.
  static int get mappedClubCount => _logoUrls.length;

  /// Возвращает адрес только для точного совпадения имени клуба.
  static String? logoUrlFor(String clubName) => _logoUrls[clubName];

  Widget _fallback() => Container(
    width: size, height: size,
    alignment: Alignment.center,
    decoration: BoxDecoration(color: fallbackColor.withValues(alpha: .22),
      borderRadius: BorderRadius.circular(borderRadius),
      border: Border.all(color: Colors.white.withValues(alpha: .12))),
    child: Icon(Icons.shield_outlined, color: Colors.white.withValues(alpha: .9), size: size * .58),
  );

  @override
  Widget build(BuildContext context) {
    final url = logoUrlFor(clubName);
    if (url == null) return _fallback();
    return SizedBox(width: size, height: size,
      child: SvgPicture.network(url, fit: BoxFit.contain,
        placeholderBuilder: (_) => _fallback(),
        errorBuilder: (_, __, ___) => _fallback()));
  }
